<?php
declare(strict_types=1);
namespace App\Commands;
use App\Services\Security\AdminPasswordResetService;use App\Services\Security\HiddenPasswordReader;use CodeIgniter\CLI\BaseCommand;use CodeIgniter\CLI\CLI;use Config\Database;use RuntimeException;
final class AdminResetPassword extends BaseCommand{protected$group='Security';protected$name='admin:reset-password';protected$description='Restablece interactivamente la contraseña de un usuario staff sin mostrarla.';protected$usage='admin:reset-password <id|email>';protected$arguments=['id|email'=>'ID numérico o correo exacto del usuario staff'];public function run(array$params):void{if(count($params)!==1||!is_string($params[0])||trim($params[0])==='')throw new RuntimeException('Uso: php spark admin:reset-password <id|email>');$reader=new HiddenPasswordReader();$password=$reader->read('Nueva contraseña: ');$confirmation=$reader->read('Confirmar contraseña: ');$result=(new AdminPasswordResetService(Database::connect('default',false)))->reset($params[0],$password,$confirmation);unset($password,$confirmation);log_message('notice','Administrative password changed for user ID {id}.',['id'=>$result['id']]);CLI::write('Contraseña administrativa actualizada para el usuario ID '.$result['id'].'.','green');}}
